SELECT CASE WHEN c.credit_limit >= 17300 THEN 'high' WHEN c.credit_limit >= 3000 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, ROUND(STDDEV(s.monthly_fee), 2) AS stddev_monthly_fee, ROUND(AVG(s.monthly_fee), 2) AS avg_monthly_fee FROM subscriptions s FULL OUTER JOIN customers c ON s.customer_id = c.id WHERE c.is_active = TRUE GROUP BY CASE WHEN c.credit_limit >= 17300 THEN 'high' WHEN c.credit_limit >= 3000 THEN 'mid' ELSE 'low' END ORDER BY stddev_monthly_fee DESC, avg_monthly_fee
